const el=(tag,cls,txt)=>{const n=document.createElement(tag);if(cls)n.className=cls;if(txt!==undefined)n.textContent=txt;return n;};
const R=['R1','R2','R3','R4','R5','R6','R7'],Q=['Q1','Q2','Q3','Q4','Q5','Q6','Q7','Q8'],CODES=[...R,...Q];
const RULES={R1:['Asset identification','PSV tag and protected-equipment consistency across the required documents.'],R2:['Serial traceability & test attribution','Trace the physical valve through work, testing and final installation.'],R3:['Datasheet pressure range','Check the applicable datasheet range against the as-left test pressure.'],R4:['Test-record consistency','Compare recorded test outcomes with the measured values and applicable test limits.'],R5:['Required document package','Check the four project-defined required document types and submission status.'],R6:['Final approval record','Check required approval identity, date and completion.'],R7:['Required information completeness','Check work order, work type and applicable work, test and installation dates.'],Q1:['Approved basis validity','Check approved basis, applicability, revision and effective status.'],Q2:['Specified set pressure','Compare the specified set pressure with the approved setpoint.'],Q3:['Approved test pressure range','Check the installed valve’s attributable as-left test against the approved range and conditions.'],Q4:['Required test compliance','Review approved test procedures, conditions, measurements and acceptance criteria.'],Q5:['Certified discharge capacity','Check approved capacity requirements and comparable certification conditions.'],Q6:['Installation compliance','Compare recorded installation checks with approved installation requirements.'],Q7:['Inspection & calibration validity','Check applicable inspection and calibration requirements, instrument validity and attributable testing.'],Q8:['Management of change (MOC)','Check applicable approved change control and justified exemptions.']};
const KEYS=['workflow_version','psv_tag','decision','a_decision','b_decision','a_issues','b_issues','test_attribution','missing_documents','rule_status','data_status','data_issues','independent_validation','facts','follow_up','reason'];
const DEC=['PASS','FAIL','REVIEW'],ST=['SATISFIED','VIOLATED','UNVERIFIED','NOT_APPLICABLE'];
const ENUM={decision:DEC,a_decision:DEC,b_decision:DEC,test_attribution:['CONFIRMED','MISMATCH','UNCONFIRMED'],data_status:['OK','ERROR','UNCERTAIN'],independent_validation:['CONFIRMED','VIOLATION_CONFIRMED','NOT_PERFORMED','UNCONFIRMED','DISAGREEMENT']};
const ARR=['a_issues','b_issues','missing_documents','data_issues','facts','follow_up'];
const DOCS=['PSV 설비 사양서','정비·교체 작업기록서','시험·교정 성적서','설치·승인 점검서'];
const object=x=>x!==null&&typeof x==='object'&&!Array.isArray(x);
function assertContract(d){
 if(!object(d))throw Error('Expected a single JSON object. Unwrap the Studio response in adapter.js.');
 const errors=[];const keys=Object.keys(d);const missing=KEYS.filter(k=>!keys.includes(k)),extra=keys.filter(k=>!KEYS.includes(k));if(missing.length)errors.push('Missing fields: '+missing.join(', '));if(extra.length)errors.push('Unexpected fields: '+extra.join(', '));
 for(const k of ['workflow_version','psv_tag','reason',...Object.keys(ENUM)])if(typeof d[k]!=='string')errors.push(k+' must be a string.');
 for(const [k,vals] of Object.entries(ENUM))if(!vals.includes(d[k]))errors.push(k+' has an unsupported enum.');
 for(const k of ARR)if(!Array.isArray(d[k])||!d[k].every(x=>typeof x==='string'))errors.push(k+' must be string[].');
 if(!object(d.rule_status))errors.push('rule_status must be an object.');else{const rk=Object.keys(d.rule_status);if(rk.length!==15||CODES.some(k=>!rk.includes(k)))errors.push('rule_status must contain exactly R1–R7 and Q1–Q8.');for(const k of CODES)if(!ST.includes(d.rule_status[k]))errors.push('Invalid rule status: '+k);}
 for(const [key,codes] of [['a_issues',R],['b_issues',Q]])if(Array.isArray(d[key])){if(d[key].some(x=>!codes.includes(x)))errors.push(key+' must contain rule codes only (e.g. Q7).');if(new Set(d[key]).size!==d[key].length||JSON.stringify(d[key])!==JSON.stringify(codes.filter(c=>d[key].includes(c))))errors.push(key+' must be unique and in rule-number order.');}
 if(Array.isArray(d.missing_documents)&&d.missing_documents.some(x=>!DOCS.includes(x)))errors.push('missing_documents contains an unsupported document label.');
 if(errors.length)throw Error(errors.join('\n'));
 // Integrity checks only. Reject conflicting results instead of manufacturing or overwriting a decision.
 for(const [key,codes] of [['a_issues',R],['b_issues',Q]]){const relevant=codes.filter(c=>['VIOLATED','UNVERIFIED'].includes(d.rule_status[c]));if(JSON.stringify(d[key])!==JSON.stringify(relevant))errors.push(key+' conflicts with rule_status.');}
 for(const [key,codes] of [['a_decision',R],['b_decision',Q]]){const s=codes.map(c=>d.rule_status[c]);if((s.includes('VIOLATED')&&d[key]!=='FAIL')||(!s.includes('VIOLATED')&&s.includes('UNVERIFIED')&&d[key]!=='REVIEW')||(s.every(x=>x==='SATISFIED'||x==='NOT_APPLICABLE')&&d[key]!=='PASS'))errors.push(key+' conflicts with rule_status.');}
 if((['FAIL'].some(x=>[d.a_decision,d.b_decision].includes(x))&&d.decision!=='FAIL')||(![d.a_decision,d.b_decision].includes('FAIL')&&[d.a_decision,d.b_decision].includes('REVIEW')&&d.decision!=='REVIEW')||(d.a_decision==='PASS'&&d.b_decision==='PASS'&&d.decision!=='PASS'))errors.push('decision conflicts with A/B decisions.');
 if(errors.length)throw Error(errors.join('\n'));return d;
}
function parseResult(input){let d=input;if(typeof d==='string'){try{d=JSON.parse(d);}catch(e){throw Error('Invalid JSON syntax. Import the exact valid final output from Studio. No automatic citation stripping or decision repair is applied.\n'+e.message);}}return isCompact(d)?assertCompact(d):isCompactDecision(d)?assertCompact({decision_output:d,followup_output:null,followup_error:'No 08 report was imported.'}):assertContract(d);}
const compactDec=['PASS','FAIL','검토 필요'];
const hasKeys=(d,ks)=>object(d)&&Object.keys(d).length===ks.length&&ks.every(k=>Object.hasOwn(d,k));
const isCompact=d=>object(d)&&Object.hasOwn(d,'decision_output');
const isCompactDecision=d=>hasKeys(d,['document_consistency','approval_compliance','reason']);
function overallFrom07(a){return ['FAIL','검토 필요','PASS'].find(x=>[a.document_consistency,a.approval_compliance].includes(x));}
function assertCompact(d){const a=d.decision_output,f=d.followup_output;if(!isCompactDecision(a)||!compactDec.includes(a.document_consistency)||!compactDec.includes(a.approval_compliance)||typeof a.reason!=='string')throw Error('Invalid 07 decision output.');let err=null;if(f!=null){if(!hasKeys(f,['overall_decision','followup_type','recipient','psv_tag','action_items','document'])||['overall_decision','followup_type','recipient','psv_tag','document'].some(k=>typeof f[k]!=='string')||!Array.isArray(f.action_items)||!f.action_items.every(x=>typeof x==='string'))err='Invalid 08 report output.';else{const expected=overallFrom07(a);const map={'FAIL':['부적합·재작업 요청서','정비·시험 담당'],'검토 필요':['보완 요청서','정비 패키지 제출자'],'PASS':['종결 검토 기록','설비 담당 승인자']};if(f.overall_decision!==expected||f.followup_type!==map[expected][0]||f.recipient!==map[expected][1]||(expected==='PASS'&&f.action_items.length))err='08 report conflicts with 07 decision.';}}const report=err?null:(f??null);return {...d,followup_output:report,followup_error:report?null:(err||d.followup_error||'08 report was not returned.'),overall_decision:overallFrom07(a),overall_source:report?'08_validated':'07_fixed_aggregation',...(err?{rejected_followup_output:f}:{})};}
const displayDecision=v=>v==='검토 필요'?'REVIEW':v;
function viewData(d){if(!isCompact(d))return d;const a=d.decision_output,f=d.followup_output;const expected=overallFrom07(a);const tag=a.reason.match(/^대상:\s*(.+?)\.\s*(?:문서 정합성|$)/)?.[1]?.trim();return {psv_tag:f?.psv_tag||tag||'PSV tag not returned',a_decision:displayDecision(a.document_consistency),b_decision:displayDecision(a.approval_compliance),decision:displayDecision(expected),overall_source:f?'08_validated':'07_fixed_aggregation'};}
window.BarrierCheckContract={keys:[...KEYS],parse:parseResult};
const sampleDefinitions=[
 {id:'01',name:'Expired instrument calibration',caption:'Consistent records, confirmed requirement violation.',tag:'PSV-DEMO-01',decision:'FAIL',a:'PASS',b:'FAIL',violated:['Q7'],unverified:[],na:['Q8'],reason:'The maintenance records are internally consistent. The test was performed after the instrument calibration validity end date, so Q7 is violated.',facts:['The test is attributable to the installed valve in this illustrative scenario.'],follow:['Obtain valid calibration and test evidence for engineering review.']},
 {id:'02',name:'Incomplete capacity evidence',caption:'A higher certified capacity alone is not sufficient.',tag:'PSV-DEMO-02',decision:'REVIEW',a:'PASS',b:'REVIEW',violated:[],unverified:['Q5'],na:['Q8'],reason:'The reported certified capacity is 6,190 kg/h and the required capacity is 5,540 kg/h. Certified backpressure is missing, so the comparison basis cannot be confirmed. Q5 remains unverified.',facts:['Certified capacity conditions and actual installation backpressure are separate evidence.'],follow:['Obtain the applicable certified backpressure or approved common comparison basis.']},
 {id:'03',name:'Complete and consistent package',caption:'All applicable review conditions are supported.',tag:'PSV-DEMO-03',decision:'PASS',a:'PASS',b:'PASS',violated:[],unverified:[],na:['Q8'],reason:'The document records are consistent and the available approved requirements are satisfied in this illustrative scenario. The documented MOC exemption is applicable.',facts:[],follow:[]}
];
function makeFixture(s){const rule_status=Object.fromEntries(CODES.map(c=>[c,s.violated.includes(c)?'VIOLATED':s.unverified.includes(c)?'UNVERIFIED':s.na.includes(c)?'NOT_APPLICABLE':'SATISFIED']));return {workflow_version:'UI fixture (v5.1.1 contract)',psv_tag:s.tag,decision:s.decision,a_decision:s.a,b_decision:s.b,a_issues:R.filter(c=>s.violated.includes(c)||s.unverified.includes(c)),b_issues:Q.filter(c=>s.violated.includes(c)||s.unverified.includes(c)),test_attribution:'CONFIRMED',missing_documents:[],rule_status,data_status:'OK',data_issues:[],independent_validation:'UNCONFIRMED',facts:s.facts,follow_up:s.follow,reason:s.reason};}
let current=null,history=[],busy=null,queue=[],nextId=0,stopRequested=false,ruleFilter="all";const adapter=()=>window.BarrierCheckAdapter;
const statusMap={PASS:['pass','✓'],FAIL:['fail','×'],REVIEW:['review','!'],SATISFIED:['satisfied','✓'],VIOLATED:['violated','×'],UNVERIFIED:['unverified','?'],NOT_APPLICABLE:['na','–'],CONFIRMED:['pass','✓'],MISMATCH:['fail','×'],UNCONFIRMED:['review','?'],OK:['pass','✓'],ERROR:['errorTone','×'],UNCERTAIN:['review','?'],VIOLATION_CONFIRMED:['fail','!'],NOT_PERFORMED:['grayTone','–'],DISAGREEMENT:['errorTone','!']};
const status=(v,prefix='')=>el('span','status '+statusMap[v][0],prefix+v);const symbol=v=>el('span','symbol '+statusMap[v][0],statusMap[v][1]);
function notice(text,type=''){const n=$('notice');n.hidden=!text;n.className='notice '+type;n.textContent=text||'';}
function page(name){for(const k of ['new','processing','result','history','guide'])$(k+'Page').hidden=k!==name;document.querySelectorAll('.nav').forEach(n=>n.classList.toggle('active',n.dataset.nav===name));$('breadcrumb').textContent={new:'New review',processing:'Processing',result:'Verification report',history:'Session history',guide:'Rule library'}[name];if(name==='history')renderHistory();if(name==='guide')renderGuide();if(name==='processing')renderQueue();window.scrollTo(0,0);}
function go(name){if(busy&&name==='new'){notice('Stop after the current case before editing the queue.');return;}if(name==='result'&&!current)return;notice('');page(name);}
document.querySelectorAll('[data-nav]').forEach(n=>n.addEventListener('click',e=>{e.preventDefault();go(n.dataset.nav);}));
function configure(){const live=adapter()?.isConnected===true&&typeof adapter().run==='function';$('engineDot').classList.toggle('live',live);$('engineText').textContent=live?'Studio target: '+(adapter().label||'configured workflow'):'Frontend preview';$('modeLabel').textContent=live?'LIVE API CONFIGURED':'PROTOTYPE · NO LIVE API';const n=queue.filter(x=>x.state==='pending').length;$('runBtn').disabled=!live||!n||!!busy;$('runBtn').textContent=n?`Run ${n} verification${n===1?'':'s'} →`:'Run verification →';$('integrationHint').textContent=live?'One API job per PDF. Files run in sequence.':'Live API not connected. Import a Studio result or explore examples.';}
function showPdf(url,name){if(!url)return;$('dialogTitle').textContent=name;$('dialogPdf').src=url;$('pdfDialog').showModal();}
$('closeDialog').addEventListener('click',()=>$('pdfDialog').close());$('pdfDialog').addEventListener('close',()=>{$('dialogPdf').removeAttribute('src');});
function addFiles(files){if(busy)return;let rejected=[];for(const file of files){if((!file.name.toLowerCase().endsWith('.pdf')&&file.type!=='application/pdf')||!file.size||file.size>30*1024*1024){rejected.push(file.name);continue;}if(queue.some(q=>q.file.name===file.name&&q.file.size===file.size&&q.file.lastModified===file.lastModified))continue;queue.push({id:++nextId,file,url:URL.createObjectURL(file),state:'pending',result:null,error:null});}renderQueue();notice(rejected.length?'Skipped non-PDF, empty or over 30 MB: '+rejected.join(', '):'',rejected.length?'error':'');}
$('pdfInput').addEventListener('change',e=>{addFiles([...e.target.files]);e.target.value='';});$('dropZone').addEventListener('click',()=>$('pdfInput').click());$('dropZone').addEventListener('keydown',e=>{if((e.key==='Enter'||e.key===' ')&&e.target===$('dropZone')){e.preventDefault();$('pdfInput').click();}});$('pickPdf').addEventListener('click',e=>{e.stopPropagation();$('pdfInput').click();});
for(const e of ['dragenter','dragover'])$('dropZone').addEventListener(e,x=>{x.preventDefault();$('dropZone').classList.add('drag');});for(const e of ['dragleave','drop'])$('dropZone').addEventListener(e,x=>{x.preventDefault();$('dropZone').classList.remove('drag');});$('dropZone').addEventListener('drop',e=>addFiles([...e.dataTransfer.files]));
function removeCase(q){if(busy)return;queue=queue.filter(x=>x!==q);if(!q.result)URL.revokeObjectURL(q.url);renderQueue();}
$('clearQueue').addEventListener('click',()=>{if(busy)return;for(const q of queue)if(!q.result)URL.revokeObjectURL(q.url);queue=[];renderQueue();});
function renderQueue(){const root=$('fileQueue');root.replaceChildren();$('queueArea').hidden=!queue.length;$('queueCount').textContent=queue.length+' PDF'+(queue.length===1?'':'s')+' selected';$('clearQueue').disabled=!!busy;for(const q of queue){const r=el('div','queuefile');const name=el('div','grow');name.append(el('strong','filename',q.file.name),el('small','muted',(q.file.size/1024/1024).toFixed(2)+' MB · '+q.state));r.append(el('span','fileicon','PDF'),name,actionButton('Preview',()=>showPdf(q.url,q.file.name),'btn ghost small'));if(q.state==='error'&&!busy)r.append(actionButton('Retry',()=>{q.state='pending';q.error=null;renderQueue();},'btn secondary small'));const rm=actionButton('×',()=>removeCase(q),'iconbtn');rm.disabled=!!busy;rm.setAttribute('aria-label','Remove '+q.file.name);r.append(rm);root.append(r);}
const counts={pending:0,running:0,done:0,error:0};for(const q of queue)counts[q.state]++;const summary=$('batchStats');summary.replaceChildren();for(const [name,num,cls] of [['Total',queue.length,''],['Completed',counts.done,'pass'],['Pending',counts.pending,''],['Error',counts.error,'fail']]){const box=el('div','batchstat '+cls);box.append(el('strong','',String(num)),el('span','',name));summary.append(box);}$('batchProgress').style.width=(queue.length?(counts.done+counts.error)/queue.length*100:0)+'%';const rows=$('batchRows');rows.replaceChildren();for(const q of queue){const r=el('div','batchrow');const name=el('div','batchfilename');name.append(el('strong','filename',q.file.name),el('small','',q.error||({pending:'Queued',running:'Review in progress…',done:'Result available',error:'Request failed'}[q.state])));r.append(name);if(q.result){const v=viewData(q.result.data);r.append(decisionSummary(v),actionButton('Open →',()=>{current=q.result;renderResult();page('result');},'btn secondary small'));}else{const state=el('span','queue-state '+q.state,q.state==='running'?'RUNNING':q.state==='error'?'ERROR':'PENDING');r.append(state);if(q.state==='error'&&!busy)r.append(actionButton('Retry',()=>{q.state='pending';q.error=null;renderQueue();},'btn secondary small'));}rows.append(r);}
$('resumeBatch').hidden=!!busy||!counts.pending;$('resumeBatch').disabled=!adapter()?.isConnected;$('batchBack').hidden=!!busy;$('cancelRun').hidden=!busy;$('cancelRun').disabled=stopRequested;$('cancelRun').textContent=stopRequested?'Stopping after current…':'Stop after current';$('batchExport').disabled=!counts.done;$('batchSummary').disabled=!counts.done;$('batchCsv').disabled=!counts.done;$('processingFile').textContent=busy?'Sequential execution · '+counts.done+' / '+queue.length+' completed':counts.pending?'Queue paused · remaining files can be run': 'Queue finished · '+counts.done+' completed, '+counts.error+' errors';$('backBatch').hidden=!queue.length;configure();}
$('importBtn').addEventListener('click',()=>$('jsonInput').click());$('jsonInput').addEventListener('change',async e=>{const f=e.target.files[0];e.target.value='';if(!f)return;try{const data=parseResult(await f.text());const q=queue.length===1?queue[0]:null;openResult(data,{type:'import',label:f.name,fileName:q?.file.name||null,url:q?.url||null});}catch(err){notice('Result not displayed: '+err.message,'error');}});
function saveHistory(data,meta){const h={data,meta,time:new Date().toISOString(),id:Date.now()+Math.random()};history.unshift(h);$('historyCount').textContent=history.length;$('resultNav').disabled=false;return h;}
async function runBatch(){if(busy||!adapter()?.isConnected||!queue.some(q=>q.state==='pending'))return;busy={};stopRequested=false;notice('');page('processing');try{for(const q of queue){if(stopRequested||q.state!=='pending'){if(stopRequested)break;continue;}q.state='running';renderQueue();const controller=new AbortController();const timeout=setTimeout(()=>controller.abort(),900000);try{const response=await adapter().run(q.file,{signal:controller.signal});const d=parseResult(response);q.result=saveHistory(d,{type:'live',label:q.file.name,fileName:q.file.name,url:q.url});q.state='done';current=q.result;}catch(err){q.error=controller.signal.aborted?'Local timeout. Check Studio monitoring before retrying.':String(err.message||err);q.state='error';stopRequested=true;}finally{clearTimeout(timeout);renderQueue();}if(!stopRequested)await new Promise(resolve=>setTimeout(resolve,300));}}finally{busy=null;stopRequested=false;renderQueue();}}
$('runBtn').addEventListener('click',runBatch);$('resumeBatch').addEventListener('click',runBatch);$('cancelRun').addEventListener('click',()=>{stopRequested=true;renderQueue();});$('batchBack').addEventListener('click',()=>page('new'));$('backBatch').addEventListener('click',()=>page('processing'));$('batchExport').addEventListener('click',()=>{const rows=queue.map(q=>({filename:q.file.name,state:q.state,error:q.error,result:q.result?.data||null}));const u=URL.createObjectURL(new Blob([JSON.stringify(rows,null,2)],{type:'application/json'}));const a=el('a');a.href=u;a.download='BarrierCheck_batch_results.json';a.click();setTimeout(()=>URL.revokeObjectURL(u),3000);});
function renderSamples(){const root=$('samples');for(const s of sampleDefinitions){const b=el('button','sample');const top=el('div','sampletop');top.append(el('span','','ILLUSTRATIVE CASE '+s.id),status(s.decision));b.append(top,el('h3','',s.name),el('p','',s.caption));const bottom=el('div','samplebottom');bottom.append(status(s.a,'A · '),status(s.b,'B · '),el('span','arrow','→'));b.append(bottom);b.addEventListener('click',()=>{if(busy)return;openResult(parseResult(makeFixture(s)),{type:'fixture',label:s.name,fileName:null,url:null});});root.append(b);}}
