function decisionSummary(v){const group=el('div','decision-summary');const main=el('div','summary-overall');main.append(el('span','summary-label','Overall'),v.decision?status(v.decision):el('span','status na','—'));const tracks=el('div','summary-tracks');for(const [letter,value] of [['A',v.a_decision],['B',v.b_decision]]){const t=el('div','summary-track');t.append(el('span','summary-label',letter),status(value));tracks.append(t);}group.append(main,tracks);return group;}
function countRules(snap,codes){return {loaded:codes.filter(c=>ST.includes(snap.status[c])).length,violated:codes.filter(c=>snap.status[c]==='VIOLATED').length,unverified:codes.filter(c=>snap.status[c]==='UNVERIFIED').length,total:codes.length};}
