function renderDecisionHeader(v,source,d){const state=v.decision||'UNAVAILABLE';const root=$('overallHero');const hero=el('div','dashboard-decision');const overall=el('div','overall-mini '+state.toLowerCase());overall.append(el('span','decision-label','OVERALL DECISION'),el('strong','overall-word',state==='UNAVAILABLE'?'—':state),el('span','overall-sub',state==='FAIL'?'Violation detected':state==='REVIEW'?'Evidence required':state==='PASS'?'Criteria satisfied':'Not returned'));hero.append(overall);const snap=snapshot(d);for(const [letter,label,decision,codes] of [['A','Document consistency',v.a_decision,R],['B','Requirement compliance',v.b_decision,Q]]){const c=el('div','track-mini '+decision.toLowerCase());const labelRow=el('div','track-label-row');labelRow.append(el('span','track-letter',letter),el('span','decision-label',label));c.append(labelRow,el('strong','track-word',decision),countLine(snap,codes));hero.append(c);}root.replaceChildren(hero);$('backBatch').hidden=!queue.length;}

