function sheetsPDF(pages){const enc=new TextEncoder(),parts=[],offsets=[0];let bytes=0;function add(s){const a=typeof s==='string'?enc.encode(s):s;parts.push(a);bytes+=a.length;}function obj(id,body){offsets[id]=bytes;add(`${id} 0 obj\n`);add(body);add('\nendobj\n');}add('%PDF-1.4\n');obj(1,'<< /Type /Catalog /Pages 2 0 R >>');obj(2,`<< /Type /Pages /Count ${pages.length} /Kids [${pages.map((_,i)=>`${3+i*3} 0 R`).join(' ')}] >>`);pages.forEach((p,i)=>{const id=3+i*3,w=p.w*0.75,h=p.h*0.75;const b64=p.canvas.toDataURL('image/jpeg',.95).split(',')[1],raw=atob(b64),jpg=Uint8Array.from(raw,c=>c.charCodeAt(0));obj(id,`<< /Type /Page /Parent 2 0 R /MediaBox [0 0 ${w} ${h}] /Resources << /XObject << /Im0 ${id+1} 0 R >> >> /Contents ${id+2} 0 R >>`);offsets[id+1]=bytes;add(`${id+1} 0 obj\n<< /Type /XObject /Subtype /Image /Width ${p.canvas.width} /Height ${p.canvas.height} /ColorSpace /DeviceRGB /BitsPerComponent 8 /Filter /DCTDecode /Length ${jpg.length} >>\nstream\n`);add(jpg);add('\nendstream\nendobj\n');const content=`q\n${w} 0 0 ${h} 0 0 cm\n/Im0 Do\nQ\n`;obj(id+2,`<< /Length ${enc.encode(content).length} >>\nstream\n${content}endstream`);});const start=bytes;add(`xref\n0 ${offsets.length}\n0000000000 65535 f \n`);for(let j=1;j<offsets.length;j++)add(`${String(offsets[j]).padStart(10,'0')} 00000 n \n`);add(`trailer\n<< /Size ${offsets.length} /Root 1 0 R >>\nstartxref\n${start}\n%%EOF\n`);return new Blob(parts,{type:'application/pdf'});}
function saveExport(blob,name){const u=URL.createObjectURL(blob),a=el('a');a.href=u;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(u),30000);}
function csvCell(v){let s=String(v??'');if(/^[\s\uFEFF]*[=+\-@\t\r]/.test(s))s="'"+s;return '"'+s.replace(/"/g,'""')+'"';}
function batchCSV(rows){const headers=['Source file','Execution state','PSV tag','Overall','A','B',...CODES,'Reported rules','Violated (reported)','Unverified (reported)','Missing rule data','Result source','Overall source','Follow-up report'];const data=rows.map(r=>{const d=r.result?.data,v=d?viewData(d):{},s=d?snapshot(d):{status:{}},n=countRules(s,CODES);return [r.name,r.state,v.psv_tag||'',v.decision||'',v.a_decision||'',v.b_decision||'',...CODES.map(c=>d?ruleLabels[s.status[c]||'NOT_RETURNED']:''),d?n.loaded:'',d&&n.loaded?n.violated:'',d&&n.loaded?n.unverified:'',d?15-n.loaded:'',d?(s.source||'No rule data'):'',d?(v.overall_source||'Final output'):'',d&&isCompact(d)?(d.followup_output?'Validated 08':'Unavailable'):''];});return '\uFEFF'+[headers,...data].map(r=>r.map(csvCell).join(',')).join('\r\n');}
$('downloadSummary').addEventListener('click',()=>{if(!current)return;try{saveExport(sheetsPDF([singleSheet(current)]),(current.meta.type==='fixture'?'ILLUSTRATIVE_':'')+safeName(exportName(current))+'_result_sheet.pdf');}catch(e){notice('PDF export failed: '+e.message,'error');}});
$('batchSummary').addEventListener('click',()=>{try{saveExport(sheetsPDF(batchSheets(queue.map(batchRow))),'BarrierCheck_batch_comparison.pdf');}catch(e){notice('PDF export failed: '+e.message,'error');}});
$('batchCsv').addEventListener('click',()=>saveExport(new Blob([batchCSV(queue.map(batchRow))],{type:'text/csv;charset=utf-8'}),'BarrierCheck_batch_comparison.csv'));

// v6+: Follow-up report (08) — preview & PDF export. Presentation only; values shown exactly as returned by 07/08.
const RPT_LABEL={FAIL:'Rework request',REVIEW:'Supplement request',PASS:'Closure record'};
function rptData(h){const d=h?.data;if(!d||!isCompact(d)||!d.followup_output)return null;const a=d.decision_output,f=d.followup_output,v=viewData(d);return {a,f,v,file:h.meta.fileName||h.meta.label||'',time:h.time,type:h.meta.type};}
function rptIssued(t){const x=new Date(t);return x.getFullYear()+'-'+String(x.getMonth()+1).padStart(2,'0')+'-'+String(x.getDate()).padStart(2,'0')+' '+String(x.getHours()).padStart(2,'0')+':'+String(x.getMinutes()).padStart(2,'0');}
function rptFileName(r){return safeName(r.file||r.f.psv_tag)+'_followup_report.pdf';}
function openReportPreview(){const r=rptData(current);if(!r)return;$('rdTitle').textContent=r.f.followup_type+' · '+r.f.psv_tag;const p=$('rdPaper');p.replaceChildren();
const head=el('div','rp-head');const brand=el('div','rp-brand');brand.append(el('strong','','BarrierCheck AI'),el('span','','ASSET INTEGRITY'));head.append(brand,el('span','rp-kind','FOLLOW-UP REPORT'));p.append(head);
const titleRow=el('div','rp-titlerow');const tt=el('div');tt.append(el('div','rp-eyebrow',(RPT_LABEL[r.v.decision]||'Follow-up').toUpperCase()),el('h2','rp-title',r.f.followup_type));titleRow.append(tt,status(r.v.decision));p.append(titleRow);
const meta=el('dl','rp-meta');for(const [k,val] of [['PSV tag',r.f.psv_tag],['Recipient',r.f.recipient],['Source package',r.file||'—'],['Issued',rptIssued(r.time)]]){const c=el('div');c.append(el('dt','',k),el('dd','',val));meta.append(c);}p.append(meta);
const dec=el('div','rp-decisions');for(const [k,val] of [['Overall',r.v.decision],['A · Document consistency',r.v.a_decision],['B · Requirement compliance',r.v.b_decision]]){const c=el('div','rp-dec');c.append(el('span','',k),status(val));dec.append(c);}p.append(dec);
p.append(el('h3','rp-h','Decision rationale'),el('p','rp-text',r.a.reason));
p.append(el('h3','rp-h','Requested actions'));if(r.f.action_items.length){const ol=el('ol','rp-actions');r.f.action_items.forEach((x,i)=>{const li=el('li');li.append(el('span','rp-no',String(i+1).padStart(2,'0')),el('span','',x));ol.append(li);});p.append(ol);}else p.append(el('p','rp-text muted','No action items. Record kept for closure review.'));
p.append(el('h3','rp-h','Document'),el('div','rp-doc',r.f.document));
const sign=el('div','rp-sign');for(const k of ['Reviewed by','Approved by']){const c=el('div');c.append(el('span','',k),el('i'));sign.append(c);}p.append(sign);
p.append(el('p','rp-foot','Generated from workflow output (07 decision · 08 follow-up). Document-based review only — not an equipment safety certification or restart approval. Engineering review and approval required.'));
const dlg=$('reportDialog');if(!dlg.open)dlg.showModal();$('rdPaper').parentElement.scrollTop=0;}
function wrapLines(ctx,text,max){const out=[];for(const para of String(text).split(/\r?\n/)){if(!para.trim()){out.push('');continue;}let line='';for(const tok of para.split(/(\s+)/)){if(!tok)continue;const tryL=line+tok;if(ctx.measureText(tryL).width<=max){line=tryL;continue;}if(line.trim())out.push(line.replace(/\s+$/,''));line=tok.replace(/^\s+/,'');while(ctx.measureText(line).width>max){let i=1;while(i<line.length&&ctx.measureText(line.slice(0,i+1)).width<=max)i++;out.push(line.slice(0,i));line=line.slice(i);}}if(line.trim())out.push(line.replace(/\s+$/,''));}return out;}
function reportPages(r){const W=794,H=1123,M=56,CW=W-M*2,pages=[];let p,ctx,y;const pal=exportPalette;
function newPage(){p=exportCanvas(W,H);ctx=p.ctx;pages.push(p);er(ctx,0,0,W,8,'#0e6965');et(ctx,'BarrierCheck AI',M,42,19,pal.ink,750);et(ctx,'FOLLOW-UP REPORT  /  '+r.f.psv_tag,W-M,42,10,pal.muted,650,'right');eline(ctx,M,64,CW);y=92;}
function need(h){if(y+h>H-86){newPage();}}
function section(t){need(50);y+=14;et(ctx,t.toUpperCase(),M,y,10.5,'#0e6965',750);y+=10;eline(ctx,M,y,CW);y+=20;}
function para(t,size=12.5,color=pal.ink,weight=400,indent=0,lh=1.6){ctx.font=`${weight} ${size}px ${exportFonts}`;for(const l of wrapLines(ctx,t,CW-indent)){need(size*lh);if(l)et(ctx,l,M+indent,y,size,color,weight);y+=size*lh;}}
newPage();
et(ctx,(RPT_LABEL[r.v.decision]||'Follow-up').toUpperCase(),M,y,10.5,pal.muted,700);y+=30;et(ctx,r.f.followup_type,M,y,26,pal.ink,750);epill(ctx,W-M-110,y-17,110,34,r.v.decision,r.v.decision);y+=36;
er(ctx,M,y,CW,92,pal.light);const cols=[['PSV TAG',r.f.psv_tag],['RECIPIENT',r.f.recipient],['SOURCE PACKAGE',r.file||'—'],['ISSUED',rptIssued(r.time)]];cols.forEach(([k,val],i)=>{const cx=M+16+(i%2)*(CW/2),cy=y+24+Math.floor(i/2)*42;et(ctx,k,cx,cy,9.5,pal.muted,700);ef(ctx,val,cx,cy+17,CW/2-32,12.5,pal.ink,600);});y+=112;
const dw=(CW-20)/3;[['OVERALL',r.v.decision],['A · DOCUMENT CONSISTENCY',r.v.a_decision],['B · REQUIREMENT COMPLIANCE',r.v.b_decision]].forEach(([k,val],i)=>{const x=M+i*(dw+10);ctx.strokeStyle=pal.line;ctx.lineWidth=1;ctx.strokeRect(x+.5,y+.5,dw-1,54);et(ctx,k,x+14,y+18,9,pal.muted,700);epill(ctx,x+14,y+29,86,18,val,val);});y+=64;
section('Decision rationale');para(r.a.reason);
section('Requested actions');if(r.f.action_items.length){r.f.action_items.forEach((x,i)=>{ctx.font=`400 12.5px ${exportFonts}`;const ls=wrapLines(ctx,x,CW-40);need(ls.length*20+8);epill(ctx,M,y-9,26,18,'NOT_APPLICABLE',String(i+1).padStart(2,'0'));ls.forEach(l=>{et(ctx,l,M+40,y,12.5,pal.ink);y+=20;});y+=6;});}else para('No action items. Record kept for closure review.',12.5,pal.muted);
section('Document');para(r.f.document,12,pal.ink,400,0,1.65);
need(110);y+=26;[['Reviewed by',M],['Approved by',M+CW/2+10]].forEach(([k,x])=>{et(ctx,k,x,y,10,pal.muted,650);er(ctx,x,y+44,CW/2-10,1,'#9fb1b8');et(ctx,'Name / Signature / Date',x,y+58,9,pal.muted);});y+=70;
pages.forEach((pg,i)=>{const c=pg.ctx;eline(c,M,H-62,CW);ef(c,'Generated from workflow output (07 decision · 08 follow-up). Not an equipment safety certification or restart approval.',M,H-44,CW-60,9.5,pal.muted);et(c,'Engineering review and approval required.',M,H-28,9.5,pal.muted);et(c,`${i+1} / ${pages.length}`,W-M,H-28,9,pal.muted,500,'right');});return pages;}
function exportReport(){const r=rptData(current);if(!r)return;try{saveExport(sheetsPDF(reportPages(r)),rptFileName(r));notice('Follow-up report exported · '+rptFileName(r),'ok');}catch(e){notice('Report export failed: '+e.message,'error');}}
$('rdClose').addEventListener('click',()=>$('reportDialog').close());$('rdExport').addEventListener('click',exportReport);$('rdPrint').addEventListener('click',()=>{document.body.classList.add('printing-report');window.print();setTimeout(()=>document.body.classList.remove('printing-report'),500);});$('reportDialog').addEventListener('click',e=>{if(e.target===$('reportDialog'))$('reportDialog').close();});
{const base=renderResult;renderResult=function(){base();if(!rptData(current))return;const pb=document.querySelectorAll('#compactPanel .report-buttons button');if(pb[0])pb[0].replaceWith(actionButton(pb[0].textContent,openReportPreview,pb[0].className));if(pb[1])pb[1].replaceWith(actionButton(pb[1].textContent,exportReport,pb[1].className));$('compactReportBody').querySelectorAll('button').forEach(b=>b.replaceWith(actionButton(b.textContent,exportReport,b.className)));};}
